import { chmodSync, existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import Database from "better-sqlite3";
import { drizzle, type BetterSQLite3Database } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { dataPaths, type DataPaths } from "../config/paths";
import * as schema from "./schema";

export type Db = BetterSQLite3Database<typeof schema>;

export interface OpenedDb {
  readonly db: Db;
  readonly sqlite: Database.Database;
  close(): void;
}

/** Generated by `npm run db:generate`; resolved from this file so the cwd does not matter. */
export const MIGRATIONS_DIR = fileURLToPath(new URL("../../drizzle", import.meta.url));

/** Creates the data directory and its subfolders (or tightens them) with mode 700. Safe to repeat. */
export function ensureDataDir(paths: DataPaths = dataPaths()): void {
  for (const folder of [paths.root, paths.backups, paths.chromeProfile, paths.screenshots, paths.logs]) {
    mkdirSync(folder, { recursive: true, mode: 0o700 });
    chmodSync(folder, 0o700);
  }
}

/**
 * Opens the app database (default: `app.db` in the data directory), creating
 * its directory with mode 700 if missing, and applies pending migrations.
 */
export function openDb(file: string = dataPaths().db): OpenedDb {
  const dir = dirname(file);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true, mode: 0o700 });
    chmodSync(dir, 0o700);
  }

  const sqlite = new Database(file);
  try {
    sqlite.pragma("journal_mode = WAL");
    sqlite.pragma("foreign_keys = ON");
    sqlite.pragma("busy_timeout = 5000");
    // A committed ledger claim must survive a power cut: losing it after the click would send a step twice.
    // FULL syncs the WAL on every commit; fullfsync makes macOS flush the drive's own cache too.
    sqlite.pragma("synchronous = FULL");
    sqlite.pragma("fullfsync = ON");
    const db = drizzle(sqlite, { schema });
    migrate(db, { migrationsFolder: MIGRATIONS_DIR });
    return { db, sqlite, close: () => sqlite.close() };
  } catch (error) {
    sqlite.close();
    throw error;
  }
}
